result:
.fill {
  width: 100%;
  height: 100%;
}

.content-box {
  width: 100%;
  height: calc(100vh - 96px);
  padding: 16px 24px 16px 24px;
  background: #fff;
  overflow: auto;
  border-radius: 4px;
}

.content-body {
  width: 100%;
  height: calc(100vh - 300px);
  position: relative;
}

.content-box :deep(.tabs.el-tabs.el-tabs--top) {
  padding-bottom: 16px;
}

.table-link-text {
  display: block;
  width: 100%;
  height: 100%;
  color: #2794f8;
  cursor: pointer;
}

.lcdp-dialog :deep(.el-dialog) {
  height: 60%;
  min-height: 500px;
  width: 970px;
}

.lcdp-dialog :deep(.el-dialog__title) {
  color: #333651;
}

:deep(.el-dialog__body) {
  padding: 0;
  width: 100%;
  height: calc(100% - 42px);
  font-size: 0;
}

.dialog-title {
  line-height: 22px;
  font-size: 16px;
  color: #333651;
  display: inline-block;
  vertical-align: middle;
}

.limit-title-length {
  max-width: 450px;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  word-break: break-all;
}

.left-mian-table {
  vertical-align: top;
  width: 50%;
  height: 100%;
  display: inline-block;
  border-right: 1px solid #eaeaea;
  padding: 10px 14px 12px 14px;
}

.question-detail-icon {
  color: #2794f8;
  display: inline-block;
  font-size: 14px;
  vertical-align: middle;
  margin-left: 5px;
}

.right-detail-table {
  width: 50%;
  height: 100%;
  display: inline-block;
  padding: 10px 14px 12px 14px;
}

.filter-btn {
  width: 100%;
  height: 32px;
  margin-bottom: 10px;
  position: relative;
}

.filter-btn.filter-title {
  font-weight: 400;
  font-size: 14px;
  color: #545672;
  line-height: 32px;
  overflow: hidden;
  text-overflow: ellipsis;
  word-break: break-all;
  white-space: nowrap;
}

.flex {
  display: flex;
}

.lcdp-dialog .filter-btn :deep(.el-input) {
  width: 160px;
}

:deep(.el-table .cell:empty::before) {
  content: '';
}

:deep(.el-table__row.selected-row),
:deep(.el-table--striped
  .el-table__body
  tr.el-table__row--striped.selected-row),
:deep(.el-table--striped
  .el-table__body
  tr.el-table__row--striped.selected-row
  td) {
  background: #e4f2ff;
}

.icon-qingqibing_xinxi {
  position: absolute;
  margin-left: 4px;
}
